<script setup>
import {computed,ref,watch} from 'vue';import {simulateCapacity} from '../sim/models/capacity.mjs';import {capacityPresets} from '../sim/scenarios.mjs';
const preset=ref('url'),rps=ref(1000),cache=ref(false),cdn=ref(false),replicas=ref(1);watch(preset,v=>{cache.value=false;cdn.value=false;rps.value=1000;replicas.value=1});const scenario=computed(()=>capacityPresets[preset.value]);const result=computed(()=>simulateCapacity({preset:preset.value,requestsPerSec:rps.value,cache:cache.value,cdn:cdn.value,replicas:replicas.value,cacheHit:scenario.value.cacheHit,objectKB:scenario.value.objectKB}));
function pct(v){return Math.round(v*100)}function label(id){return {app:'App',db:'Database',cache:'Cache',cdn:'CDN',origin:'Object Storage'}[id]||id}
</script><template><section class="sim-lab"><div class="sim-controls"><div><span>情境</span><div class="sim-segment"><button v-for="(s,id) in capacityPresets" :key="id" :aria-pressed="preset===id" @click="preset=id">{{s.label}}</button></div><small>{{scenario.description}}</small></div><div><span>流量：{{rps.toLocaleString()}} req/s</span><input v-model.number="rps" type="range" min="1000" max="100000" step="1000"></div><div><span>改架構</span><div class="sim-segment"><button v-if="preset!=='video'" :aria-pressed="cache" @click="cache=!cache">Cache {{cache?'ON':'OFF'}}</button><button v-if="preset==='video'" :aria-pressed="cdn" @click="cdn=!cdn">CDN {{cdn?'ON':'OFF'}}</button><button v-if="preset!=='video'" @click="replicas=Math.min(4,replicas+1)">App × {{replicas}}</button></div></div></div><div class="sim-system sim-system-nodes"><template v-for="(n,i) in result.nodes" :key="n.id"><div v-if="i" class="sim-arrow">→</div><div :class="['sim-node',{'is-critical':n.status==='critical','is-warning':n.status==='warning'}]"><b>{{label(n.id)}}</b><span>{{n.incoming.toLocaleString()}} QPS · {{pct(n.utilization)}}%</span><div class="sim-util"><i :style="{width:Math.min(100,pct(n.utilization))+'%'}"></i></div></div></template></div><div class="sim-metrics"><div><span>Throughput</span><strong>{{result.throughput.toLocaleString()}} /s</strong></div><div><span>估計路徑延遲</span><strong>{{Math.round(result.totalLatency)}} ms</strong></div><div><span>Origin bandwidth</span><strong>{{Math.round(result.bandwidthMbps)}} Mbps</strong></div><div :class="{'is-bad':result.bottlenecks.length}"><span>Bottleneck</span><strong>{{result.bottlenecks.length?result.bottlenecks.map(label).join('、'):'目前沒有'}}</strong></div></div><div class="sim-consequence"><strong>觀察改動，不找固定答案</strong><p>調高流量，再開啟 Cache / CDN 或增加 App replicas。只有被這個改動影響的 node 指標會改變；如果 bottleneck 留在別處，整體限制也會留下。</p></div></section></template>